// View-only customer grouping; never derives identities from names or different source versions.
import {weekendCustomerIdentities} from '../hosted/weekend-customer-identities.mjs';
import {createHash} from 'node:crypto';
const hex=x=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x),validKey=k=>typeof k==='string'&&/^\d{4}-\d{2}-\d{2}\/.{1,200}$/.test(k);
export function weekendIdentityView(entries){if(!entries||typeof entries!=='object'||Array.isArray(entries)||Object.keys(entries).length>100000)throw Error('Invalid weekend identity bindings');return Object.fromEntries(Object.entries(entries).map(([key,v])=>{if(!validKey(key)||!hex(v?.sourceSha256)||!hex(v?.customerHash))throw Error('Invalid weekend identity binding');return [key,v.customerHash]}));}
export function buildWeekendIdentityEntries(rows,snapshots,previous={}){if(!Array.isArray(rows)||!Array.isArray(snapshots))throw Error('Invalid weekend identity inputs');weekendIdentityView(previous);const byKey=new Map();for(const row of rows){if(!validKey(row?.key)||row.key!==row.date+'/'+row.delivery?.delivery_id||byKey.has(row.key))throw Error('Ambiguous weekend delivery identity');byKey.set(row.key,row);}const fresh=weekendCustomerIdentities(rows,snapshots),entries=[];for(const row of rows){const weekday=new Date(row.date+'T12:00:00Z').getUTCDay(),sourceSha256=row.delivery?.source_sha256;if((weekday!==0&&weekday!==6)||!hex(sourceSha256))continue;const old=previous[row.key],current=fresh[row.key],retained=old?.sourceSha256===sourceSha256?old.customerHash:null;if(retained&&current&&retained!==current)throw Error('Weekend identity conflict');const customerHash=current||retained;if(customerHash)entries.push([row.key,{sourceSha256,customerHash}]);}return Object.fromEntries(entries);}
export async function readWeekendIdentityCheckpoint(repository,head,pointer){if(!pointer)return null;if(!hex(pointer.sha256)||pointer.path!=='weekend-identities/'+pointer.sha256+'.json'||pointer.reportHash!==head?.reportHash)throw Error('Invalid weekend identity pointer');let bytes;try{bytes=await repository.readFile('state',pointer.path,{maxBytes:16*1024*1024});}catch(e){if(e.code!=='ENOENT')throw e;bytes=await repository.readFile('archive',pointer.path,{maxBytes:16*1024*1024});}if(!Buffer.isBuffer(bytes)||createHash('sha256').update(bytes).digest('hex')!==pointer.sha256)throw Error('Weekend identity integrity failure');const doc=JSON.parse(bytes);if(doc?.version!==1||doc.reportHash!==head.reportHash||doc.manifestSha256!==head.manifest?.sha256||doc.originalSha!==head.originalSha)throw Error('Weekend identity report binding failure');weekendIdentityView(doc.entries);return doc;}
